export const changelogEntryTypes = ["added", "changed", "fixed", "removed", "security"] as const;

export type ChangelogEntryType = (typeof changelogEntryTypes)[number];

export type ChangelogEntry = {
  type: ChangelogEntryType;
  title: string;
  body: string;
};

export type ChangelogRelease = {
  version: string;
  date: string;
  entries: ChangelogEntry[];
};

export type Changelog = {
  schemaVersion: 1;
  releases: ChangelogRelease[];
};

const versionPattern = /^(\d+)\.(\d+)\.(\d+)/;
const datePattern = /^\d{4}-\d{2}-\d{2}$/;

function isEntryType(value: unknown): value is ChangelogEntryType {
  return changelogEntryTypes.some((type) => type === value);
}

function parseEntry(value: unknown, where: string): ChangelogEntry {
  if (typeof value !== "object" || value === null) {
    throw new Error(`${where} must be an object`);
  }
  if (!("type" in value) || !isEntryType(value.type)) {
    throw new Error(`${where}.type must be one of ${changelogEntryTypes.join(", ")}`);
  }
  if (!("title" in value) || typeof value.title !== "string" || value.title === "") {
    throw new Error(`${where}.title must be a non-empty string`);
  }
  if (!("body" in value) || typeof value.body !== "string") {
    throw new Error(`${where}.body must be a string`);
  }
  return { type: value.type, title: value.title, body: value.body };
}

function parseRelease(value: unknown, where: string): ChangelogRelease {
  if (typeof value !== "object" || value === null) {
    throw new Error(`${where} must be an object`);
  }
  if (
    !("version" in value) ||
    typeof value.version !== "string" ||
    !versionPattern.test(value.version)
  ) {
    throw new Error(`${where}.version must be a semver version`);
  }
  if (!("date" in value) || typeof value.date !== "string" || !datePattern.test(value.date)) {
    throw new Error(`${where}.date must be an ISO date (YYYY-MM-DD)`);
  }
  if (!("entries" in value) || !Array.isArray(value.entries)) {
    throw new Error(`${where}.entries must be an array`);
  }
  const entries = value.entries.map((entry, index) =>
    parseEntry(entry, `${where}.entries[${index}]`),
  );
  return { version: value.version, date: value.date, entries };
}

/** Compares the major.minor.patch parts of two versions. Pre-release suffixes are ignored. */
export function compareVersions(a: string, b: string): number {
  const partsA = versionPattern.exec(a);
  const partsB = versionPattern.exec(b);
  if (!partsA || !partsB) return 0;
  for (let index = 1; index <= 3; index += 1) {
    const difference = Number(partsA[index]) - Number(partsB[index]);
    if (difference !== 0) return difference;
  }
  return 0;
}

/** Validates the changelog.json written by `q9 changelog export` and returns releases newest first. */
export function parseChangelog(input: unknown): Changelog {
  if (typeof input !== "object" || input === null) {
    throw new Error("changelog.json must be an object");
  }
  if (!("schemaVersion" in input) || input.schemaVersion !== 1) {
    throw new Error("changelog.json schemaVersion must be 1");
  }
  if (!("releases" in input) || !Array.isArray(input.releases)) {
    throw new Error("changelog.json releases must be an array");
  }
  const releases = input.releases
    .map((release, index) => parseRelease(release, `changelog.json releases[${index}]`))
    .toSorted((a, b) => compareVersions(b.version, a.version));
  return { schemaVersion: 1, releases };
}

import * as React from "react";

import { compareVersions, type Changelog } from "@/lib/changelog";

const storageKey = "q9:changelog:last-seen";

function subscribe(onChange: () => void) {
  window.addEventListener("storage", onChange);
  return () => window.removeEventListener("storage", onChange);
}

function readLastSeen() {
  return window.localStorage.getItem(storageKey);
}

// On the server the last seen version is unknown, so nothing counts as unseen.
function readLastSeenOnServer() {
  return undefined;
}

export function useChangelog(data: Changelog) {
  const latestVersion = data.releases[0]?.version;
  const lastSeenVersion = React.useSyncExternalStore(subscribe, readLastSeen, readLastSeenOnServer);

  const hasUnseen =
    latestVersion !== undefined &&
    lastSeenVersion !== undefined &&
    (lastSeenVersion === null || compareVersions(latestVersion, lastSeenVersion) > 0);

  const markSeen = React.useCallback(() => {
    if (latestVersion === undefined) return;
    window.localStorage.setItem(storageKey, latestVersion);
    // The storage event only fires in other tabs, so notify this one too.
    window.dispatchEvent(new StorageEvent("storage", { key: storageKey }));
  }, [latestVersion]);

  return { hasUnseen, latestVersion, markSeen };
}

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  changelogEntryTypes,
  type Changelog,
  type ChangelogEntryType,
  type ChangelogRelease,
} from "@/lib/changelog";

export type ChangelogLabels = {
  title: string;
  description: string;
  empty: string;
  version: (version: string) => string;
  types: Record<ChangelogEntryType, string>;
};

const defaultChangelogLabels: ChangelogLabels = {
  title: "Changelog",
  description: "Changes in recent releases, newest first.",
  empty: "No release notes yet. New features and fixes will appear here after the next release.",
  version: (version) => `Version ${version}`,
  types: {
    added: "New",
    changed: "Changed",
    fixed: "Fixed",
    removed: "Removed",
    security: "Security",
  },
};

type ChangelogDialogProps = {
  data: Changelog;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Translated copy. Defaults to English. */
  labels?: ChangelogLabels;
  /** BCP 47 locale for dates. Defaults to the `lang` attribute of the document. */
  locale?: string;
};

function formatReleaseDate(date: string, locale: string | undefined) {
  // Release dates are calendar days, so format them in UTC to avoid shifting by a day.
  return new Intl.DateTimeFormat(locale, { dateStyle: "long", timeZone: "UTC" }).format(
    new Date(`${date}T00:00:00Z`),
  );
}

function documentLocale() {
  if (typeof document === "undefined") return undefined;
  return document.documentElement.lang || undefined;
}

function ReleaseNotes({
  release,
  labels,
  locale,
}: {
  release: ChangelogRelease;
  labels: ChangelogLabels;
  locale: string | undefined;
}) {
  const groups = changelogEntryTypes
    .map((type) => ({ type, entries: release.entries.filter((entry) => entry.type === type) }))
    .filter((group) => group.entries.length > 0);

  return (
    <article className="flex flex-col gap-3">
      <header className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
        <h3 className="font-medium">{labels.version(release.version)}</h3>
        <time dateTime={release.date} className="text-muted-foreground">
          {formatReleaseDate(release.date, locale)}
        </time>
      </header>
      {groups.map((group) => (
        <section key={group.type} className="flex flex-col gap-2">
          <h4 className="text-muted-foreground">{labels.types[group.type]}</h4>
          <ul className="flex flex-col gap-2">
            {group.entries.map((entry) => (
              <li key={entry.title}>
                <p className="font-medium">{entry.title}</p>
                {entry.body !== "" && <p className="text-muted-foreground">{entry.body}</p>}
              </li>
            ))}
          </ul>
        </section>
      ))}
    </article>
  );
}

export function ChangelogDialog({
  data,
  open,
  onOpenChange,
  labels = defaultChangelogLabels,
  locale = documentLocale(),
}: ChangelogDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{labels.title}</DialogTitle>
          <DialogDescription>{labels.description}</DialogDescription>
        </DialogHeader>
        {data.releases.length === 0 ? (
          <p className="rounded-md bg-muted p-4 text-muted-foreground">{labels.empty}</p>
        ) : (
          <ol className="-me-4 flex max-h-96 flex-col divide-y overflow-y-auto pe-4">
            {data.releases.map((release) => (
              <li key={release.version} className="py-4 first:pt-0 last:pb-0">
                <ReleaseNotes release={release} labels={labels} locale={locale} />
              </li>
            ))}
          </ol>
        )}
      </DialogContent>
    </Dialog>
  );
}
